1	import javax.swing.*;
2	import java.awt.*;
3	import java.awt.event.ActionListener;
4	import java.util.ArrayList;
5	import java.util.HashMap;
6	
7	/**
8	 * Builds and handles the view of the GUI in which user can choose the habitat, animals,
9	 * and climate change scenario to be implemented in their simulation.
10	 *
11	 * @version 2022.03.02
12	 */
13	public class MenuView
14	{
15	    // The GUIHandler object governing the GUI.
16	    private GUIHandler handler;
17	    // The list of habitats to choose from.
18	    private ArrayList<String> habitatList;
19	    // The list of animals to choose from.
20	    private ArrayList<String> animalList;
21	    // The list of climate change scenario to choose from.
22	    private ArrayList<String> climateChangeScenarioList;
23	    // The list of JTextField receiving the number of animals inputted by the user.
24	    private ArrayList<JTextField> animalNumberReceivers;
25	    // The HashMap storing animals chosen by the user.
26	    private HashMap<String, Integer> selectedAnimals;
27	    // Tool to alert user about any potential error.
28	    private ErrorThrower errorThrower;
29	
30	    /**
31	     * Initializes all fields with the appropriate list of animal,
32	     * habitat and climate change scenario choices as well as the GUIHandler
33	     * currently governing the GUI.
34	     *
35	     * @param handler (GUIHandler) the GUIHandler currenly handling the GUI.
36	     * @param animalChoices (ArrayList<String>) The list of animal choices.
37	     * @param habitatChoices (ArrayList<String>) The list of habitat choices.
38	     * @param scenarioChoices (ArrayList<String>) The list of climate change scenario choices.
39	     */
40	    public MenuView (GUIHandler handler, ArrayList<String> animalChoices, ArrayList<String> habitatChoices, ArrayList<String> scenarioChoices)
41	    {
42	        habitatList = habitatChoices;
43	        animalList = animalChoices;
44	        climateChangeScenarioList = scenarioChoices;
45	        this.handler = handler;
46	        animalNumberReceivers = new ArrayList<>();
47	        selectedAnimals = new HashMap<>();
48	        errorThrower = new ErrorThrower();
49	    }
50	
51	    /**
52	     * Create and return the menu view UI.
53	     *
54	     * @return (JFrame) The created menu view UI.
55	     */
56	    public JFrame createAndShow()
57	    {
58	        // Create frame and set title and minimal size.
59	        JFrame frame = new JFrame("Ultimate Simulator 3000");
60	        frame.setMinimumSize(new Dimension(600,450));
61	
62	        JPanel mainContainer = new JPanel(new BorderLayout());
63	        mainContainer.setBorder(BorderFactory.createEmptyBorder(5,5,5,5));
64	
65	        JLabel welcomeLabel = createWelcomeLabel("Welcome to the Ultimate Simulator 3000");
66	        // HABITAT CHOICE SECTION
67	        JComboBox habitatListDisplay = createListDisplayFromList(habitatList);
68	        Box habitatChoiceComponent = createHabitatChoiceComponent(habitatListDisplay);
69	        // CLIMATE CHANGE SCENARIO CHANGE SECTION
70	        JComboBox scenarioListDisplay = createListDisplayFromList(climateChangeScenarioList);
71	        Box scenarioChoiceComponent = createScenarioChoiceComponent(scenarioListDisplay);
72	        // ANIMAL CHOICE SECTION
73	        JPanel animalChoiceComponent = createAnimalChoiceComponent();
74	
75	        // SIMULATE BUTTON
76	        JButton actionButton = new JButton("Simulate");
77	        ActionListener launchSim = e -> {
78	            getInputsAndLaunchSimulation(habitatListDisplay, animalNumberReceivers, scenarioListDisplay);
79	        };
80	        actionButton.addActionListener(launchSim);
81	
82	        // PUTTING THE UI TOGETHER
83	        Box choiceComponents = Box.createVerticalBox();
84	        choiceComponents.setBorder(BorderFactory.createEmptyBorder(30,0,10,0));
85	        choiceComponents.add(habitatChoiceComponent);
86	        choiceComponents.add(scenarioChoiceComponent);
87	        choiceComponents.add(animalChoiceComponent);
88	
89	        mainContainer.add(welcomeLabel, BorderLayout.NORTH);
90	        mainContainer.add(choiceComponents, BorderLayout.CENTER);
91	        mainContainer.add(actionButton, BorderLayout.SOUTH);
92	
93	        frame.getContentPane().add(mainContainer);
94	        return frame;
95	    }
96	
97	    /**
98	     * Create a welcome label with a given text. Welcome label is characterized by its large bold font.
99	     * @param welcomeText (String) The text to be displayed.
100	     * @return (JLabel) The JLabel created.
101	     */
102	    private JLabel createWelcomeLabel(String welcomeText)
103	    {
104	        JLabel welcomeLabel = new JLabel(welcomeText);
105	        welcomeLabel.setFont(new Font("Dialog", Font.BOLD, 27));
106	        welcomeLabel.setHorizontalAlignment(SwingConstants.CENTER);
107	        
108	        return welcomeLabel;
109	    }
110	
111	    /**
112	     * Create a JComboBox out of a list. This allows other classes to display
113	     * the JComboBox and let users make their choices that way.
114	     *
115	     * @param list (ArrayList<String>) The list to be displayed.
116	     * @return (JComboBox) The created JComboBox.
117	     */
118	    private JComboBox createListDisplayFromList (ArrayList<String> list)
119	    {
120	        JComboBox listDisplay = new JComboBox();
121	        for (String element : list) {
122	            listDisplay.addItem(element);
123	        }
124	        return listDisplay;
125	    }
126	
127	
128	    /**
129	     * Create the part of the GUI that allows users to choose a habitat for their simulation.
130	     * @param habitatListDisplay (JComboBox) The JComboBox allowing user to make his/her choice.
131	     * @return (Box) The part of the GUI that was created.
132	     */
133	    private Box createHabitatChoiceComponent(JComboBox habitatListDisplay)
134	    {
135	        Box habitatChoiceComponent = Box.createHorizontalBox();
136	        JLabel habitatChoicePrompt = new JLabel("Choose a habitat for your simulation:");
137	        habitatChoiceComponent.add(habitatChoicePrompt);
138	        habitatChoiceComponent.add(habitatListDisplay);
139	        
140	        return habitatChoiceComponent;
141	    }
142	
143	    /**
144	     * Create the part of the GUI that allows users to choose a
145	     * climate change scenario for their simulation.
146	     *
147	     * @param scenarioListDisplay (JComboBox) The JComboBox allowing user to make his/her choice.
148	     * @return (Box) The part of the GUI that was created.
149	     */
150	    private Box createScenarioChoiceComponent(JComboBox scenarioListDisplay)
151	    {
152	        Box scenarioChoiceComponent = Box.createHorizontalBox();
153	        JLabel scenarioChoicePrompt = new JLabel("Choose a climate change scenario:");
154	        scenarioChoiceComponent.add(scenarioChoicePrompt);
155	        scenarioChoiceComponent.add(scenarioListDisplay);
156	        
157	        return scenarioChoiceComponent;
158	    }
159	
160	    /**
161	     * Create the component to guide users through their choice of animals and allow them to make such choice.
162	     * @return (JPanel) The created UI component.
163	     */
164	    private JPanel createAnimalChoiceComponent()
165	    {
166	        JPanel animalChoiceComponent = new JPanel();
167	        animalChoiceComponent.setLayout(new BorderLayout());
168	
169	        // Labels to guide animals choice.
170	        JLabel animalChoicePrompt = new JLabel("Please choose the animals you want to see evolve in this habitat:");
171	        JLabel animalChoiceExplanationPrompt = new JLabel("(Input the number of each of these animals you want to include, we recommend adding twice the number of preys than predators)");
172	        animalChoicePrompt.setAlignmentX(JLabel.CENTER_ALIGNMENT);
173	        animalChoiceExplanationPrompt.setAlignmentX(JLabel.CENTER_ALIGNMENT);
174	        // Technique to set the italic font: https://java2everyone.blogspot.com/2008/12/set-jlabel-text-italic.html?m=0
175	        Font italicFont = new Font(animalChoiceExplanationPrompt.getFont().getName(),Font.ITALIC,animalChoiceExplanationPrompt.getFont().getSize());
176	        animalChoiceExplanationPrompt.setFont(italicFont);
177	
178	        // Setting the Layout of the two created labels.
179	        JPanel animalPrompts = new JPanel();
180	        animalPrompts.setLayout(new BoxLayout(animalPrompts, BoxLayout.PAGE_AXIS));
181	
182	        animalPrompts.add(Box.createVerticalGlue());
183	        animalPrompts.add(animalChoicePrompt);
184	        animalPrompts.add(animalChoiceExplanationPrompt);
185	        animalPrompts.add(Box.createRigidArea(new Dimension(0, 20)));
186	
187	        JPanel animalListDisplay = createAnimalListDisplay();
188	
189	        animalChoiceComponent.add(animalPrompts, BorderLayout.CENTER);
190	        animalChoiceComponent.add(animalListDisplay, BorderLayout.PAGE_END);
191	        
192	        return animalChoiceComponent;
193	    }
194	
195	    /**
196	     * Create a display to allow users to choose the number of each animal they want.
197	     * @return (JPanel) The created display.
198	     */
199	    private JPanel createAnimalListDisplay()
200	    {
201	        GridLayout animalListDisplayLayout = new GridLayout(0,5);
202	        animalListDisplayLayout.setHgap(10);
203	        animalListDisplayLayout.setVgap(7);
204	
205	        JPanel animalListDisplay = new JPanel(animalListDisplayLayout);
206	
207	        for (String animalName : animalList) {
208	            Box animalComponent = Box.createHorizontalBox();
209	            // technique to capitalize first letter : https://stackoverflow.com/questions/3904579/how-to-capitalize-the-first-letter-of-a-string-in-java
210	            String capitalizedAnimalName = animalName.substring(0, 1).toUpperCase() + animalName.substring(1);
211	            JLabel animalNameDisplay = new JLabel(capitalizedAnimalName);
212	            animalComponent.add(animalNameDisplay);
213	            JTextField animalNumber = new JTextField();
214	            animalNumber.setText("0");
215	            animalNumberReceivers.add(animalNumber);
216	            animalComponent.add(animalNumber);
217	            animalListDisplay.add(animalComponent);
218	        }
219	
220	        return animalListDisplay;
221	    }
222	
223	    /**
224	     * Retrieves all inputs in the correct form using helper methods
225	     * defined in this class and launches the simulation.
226	     *
227	     * @param habitatChoiceDisplay (JComboBox) The ComboBox used by the user to select a habitat.
228	     * @param animalNumberReceivers (ArrayList<JTextField>) The list of TextFields used by the user to input numbers of each animal to create.
229	     * @param climateChangeScenarioChoiceDisplay (ComboBox) The ComboBox used by the user to select a climate change scenario.
230	     */
231	    private void getInputsAndLaunchSimulation(JComboBox habitatChoiceDisplay, ArrayList<JTextField> animalNumberReceivers, JComboBox climateChangeScenarioChoiceDisplay)
232	    {
233	        String chosenHabitat = getHabitatInput(habitatChoiceDisplay);
234	        if (chosenHabitat != null)
235	        {
236	            ArrayList<Integer> numbersInputted = getNumericValuesOfUserInputs(animalNumberReceivers);
237	            if (numbersInputted != null) {
238	                boolean generationSuccessful = generateAnimalDictionary(numbersInputted);
239	                if (generationSuccessful) {
240	                    String chosenSimulation = getScenarioInput(climateChangeScenarioChoiceDisplay);
241	                    launchSimulation(chosenHabitat, chosenSimulation);
242	                }
243	            }
244	        }
245	    }
