247	    /**
248	     * Return a list of Integers from the Strings inputted by the user in the various TextFields.
249	     * Source for try/catch construct to catch non-numerical values: https://stackabuse.com/java-check-if-string-is-a-number/
250	     *
251	     * @param inputsList (ArrayList<JTextField>) The list of TextFields object in which the user inputted data.
252	     * @return (ArrayList<Integer>) The list of integers inputted by the user.
253	     */
254	    private ArrayList<Integer> getNumericValuesOfUserInputs (ArrayList<JTextField> inputsList)
255	    {
256	        ArrayList<Integer> inputtedNumbers = new ArrayList<>();
257	        for (JTextField inputReceiver : inputsList)
258	        {
259	            String inputValue = inputReceiver.getText();
260	            try {
261	                int numericValue = Integer.parseInt(inputValue);
262	                inputtedNumbers.add(numericValue);
263	            } catch (NumberFormatException e) {
264	                throwErrorMessage("One of the values inputted is not a number or one cell was left blank, please try again.");
265	            }
266	        }
267	        return inputtedNumbers;
268	    }
