279	    /**
280	     * Generates a HashMap associating the name of each animal with the number
281	     * of this animal that must be created. This method heavily relies on the fact
282	     * that animal names are stored in the animalList in the same order that they were on screen.
283	     *
284	     * @param numberOfEachAnimals (ArrayList<Integer>) The String object to test.
285	     */
286	    private boolean generateAnimalDictionary(ArrayList<Integer> numberOfEachAnimals)
287	    {
288	        if (numberOfEachAnimals.size() == animalList.size())
289	        {
290	            for (int i=0; i<numberOfEachAnimals.size(); i++) {
291	                selectedAnimals.put(animalList.get(i), numberOfEachAnimals.get(i));
292	            }
293	        }
294	        else {
295	            return false;
296	        }
297	        return true;
298	    }
