253	    /**
254	     * Provide a graphical view of a rectangular field. This is a nested class (a class defined inside a class) which defines a
255	     * custom component for the user interface. This component displays the field.
256	     * This is rather advanced GUI stuff - you can ignore this for your project if you like.
257	     */
258	    class FieldView extends JPanel
259	    {
260	        private final int GRID_VIEW_SCALING_FACTOR = 6;
261	
262	        private int gridWidth, gridHeight;
263	        private int xScale, yScale;
264	        Dimension size;
265	        private Graphics g;
266	        private Image fieldImage;
267	
268	        /**
269	         * Create a new FieldView component.
270	         */
271	        public FieldView(int height, int width)
272	        {
273	            gridHeight = height;
274	            gridWidth = width;
275	            size = new Dimension(0, 0);
276	        }
277	
278	        /**
279	         * Tell the GUI manager how big we would like to be.
280	         */
281	        public Dimension getPreferredSize()
282	        {
283	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
284	                    gridHeight * GRID_VIEW_SCALING_FACTOR);
285	        }
286	
287	        /**
288	         * Prepare for a new round of painting. Since the component may be resized, compute the scaling factor again.
289	         */
290	        public void preparePaint()
291	        {
292	            if(! size.equals(getSize())) {  // if the size has changed...
293	                size = getSize();
294	                fieldImage = fieldView.createImage(size.width, size.height);
295	                g = fieldImage.getGraphics();
296	
297	                xScale = size.width / gridWidth;
298	                if(xScale < 1) {
299	                    xScale = GRID_VIEW_SCALING_FACTOR;
300	                }
301	                yScale = size.height / gridHeight;
302	                if(yScale < 1) {
303	                    yScale = GRID_VIEW_SCALING_FACTOR;
304	                }
305	            }
306	        }
307	
308	        /**
309	         * Paint on grid location on this field in a given color.
310	         */
311	        public void drawMark(int x, int y, Color color)
312	        {
313	            g.setColor(color);
314	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
315	        }
316	
317	        /**
318	         * The field view component needs to be redisplayed. Copy the internal image to screen.
319	         */
320	        public void paintComponent(Graphics g)
321	        {
322	            if(fieldImage != null) {
323	                Dimension currentSize = getSize();
324	                if(size.equals(currentSize)) {
325	                    g.drawImage(fieldImage, 0, 0, null);
326	                }
327	                else {
328	                    // Rescale the previous image.
329	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
330	                }
331	            }
332	        }
333	    }
334	}

