216	    /**
217	     * Find an available location for an object to be created in the simulation field.
218	     * The simulation is chosen at random and is changed if the randomly selected cell
219	     * already contains an object.
220	     *
221	     * @param field (Field) The simulation's field.
222	     * @return (Location) the available location found.
223	     */
224	    private Location findAvailableLocation(Field field)
225	    {
226	        int randomWidth = rand.nextInt(DEFAULT_WIDTH);
227	        int randomDepth = rand.nextInt(DEFAULT_DEPTH);
228	        while (field.getObjectAt(randomDepth,randomWidth) != null) {
229	            randomWidth = rand.nextInt(DEFAULT_WIDTH);
230	            randomDepth = rand.nextInt(DEFAULT_DEPTH);
231	        }
232	        return new Location(randomDepth, randomWidth);
233	    }
