1	/**
2	 * This class reads from "animals.csv" the information about all the animals
3	 * that are available to be put in the simulation.
4	 *
5	 * @version 2022.02.28
6	 */
7	
8	public class AnimalCSVReader extends CSVReader
9	{
10	    // Path to the file holding the animal related data.
11	    private static final String FILE_NAME = "animals.csv";
12	    // String to be recognized as a boolean value of true.
13	    private static final String TRUE_SYMBOL = "true";
14	    // tru if the animal is a predator.
15	    private boolean isPredator;
16	    // Animal's name.
17	    private String name;
18	    // Maximum temperature the animal can survive to.
19	    private int maximumTemperature;
20	    // Minimum temperature the animal can survive to.
21	    private int minimumTemperature;
22	    // Maximum Age animal can live for.
23	    private int maximumAge;
24	    // Minimum age at which animal can breed.
25	    private int breedingAge;
26	    // Probability to see animal breed at each step.
27	    private double breedingProbability;
28	    // Maximum litter size brought by animal in one reproduction.
29	    private int maxLitterSize;
30	    // Nutritional value brought when animal is eaten.
31	    private int nutritionalValue;
32	    // Animal's strength (0 if not a predator).
33	    private int strength;
34	    // Whether an animal can hibernate.
35	    private boolean hibernates;
36	    // Whether an animal is nocturnal.
37	    private boolean isNocturnal;
38	    // Tool to alert user about any potential error.
39	    private ErrorThrower errorThrower;
40	
41	    /**
42	     * Builds an AnimalCSVReader and initializes field.
43	     */
44	    public AnimalCSVReader() {
45	        errorThrower = new ErrorThrower();
46	        isPredator = false;
47	        name = null;
48	        maximumTemperature = 0;
49	        minimumTemperature = 0;
50	        maximumAge = 0;
51	        breedingAge = 0;
52	        breedingProbability = 0;
53	        maxLitterSize = 0;
54	        nutritionalValue = 0;
55	        strength = 0;
56	        hibernates = false;
57	        isNocturnal = false;
58	
59	    }
60	
61	    /**
62	     * Populated fields with the data read from the files. This method overrides
63	     * a method of the CSVReader parent class and is therefore called after reading the data.
64	     *
65	     * @param extractedData (String[]) The data read.
66	     */
67	    protected void populateFields(String[] extractedData)
68	    {
69	        if (extractedData.length != 12) {
70	            errorThrower.throwMessage("Animal .csv issue, please restart.");
71	        }
72	        name = extractedData[0];
73	        if (extractedData[1].equals(TRUE_SYMBOL)) {
