53	
54	        for(int i = 0; i < extractedData.length; i++) {
55	            if(i/2 == 0) {
56	                winterTemperatures[i%2] = Integer.parseInt(extractedData[i]);
57	            } else if (i/2 == 1) {
58	                springTemperatures[i%2] = Integer.parseInt(extractedData[i]);
59	            } else if (i/2 == 2) {
60	                summerTemperatures[i%2] = Integer.parseInt(extractedData[i]);
61	            } else if (i/2 == 3){
62	                autumnTemperatures[i%2] = Integer.parseInt(extractedData[i]);
