87	     */
88	    private String[] removeHabitatName(String[] attributes)
89	    {
90	        String[] attributesWithoutHabitatName = Arrays.copyOfRange(attributes,1,attributes.length);
91	        return attributesWithoutHabitatName;
92	    }
